(function(){
  if(window.__HCInesOfficialVisualV7)return;
  window.__HCInesOfficialVisualV7=true;

  const FULL='data:image/webp;base64,';
  const PORTRAIT='data:image/webp;base64,';
  const $=(s,r=document)=>r.querySelector(s);

  function installCss(){
    if($('#hcInesOfficialVisualV7Styles'))return;
    const s=document.createElement('style');
    s.id='hcInesOfficialVisualV7Styles';
    s.textContent=`
      #characters .hc-person[data-id="ines"]{opacity:1!important;filter:none!important}
      #characters .hc-person[data-id="ines"] .fig{
        overflow:hidden!important;
        border-radius:18px!important;
        background:radial-gradient(circle at 50% 34%,#fffdf9 0 39%,#f8eee2 78%,#f2e3d4 100%)!important;
      }
      #characters .hc-person[data-id="ines"] .fig img.hc-ines-official-v7{
        display:block!important;
        position:absolute!important;
        inset:0!important;
        width:100%!important;
        height:100%!important;
        object-fit:contain!important;
        object-position:50% 100%!important;
        transform:none!important;
        filter:drop-shadow(0 9px 9px rgba(73,50,38,.08))!important;
        mix-blend-mode:normal!important;
        background:transparent!important;
        border:0!important;
      }
      #characters .hc-person[data-id="ines"] .tag:before{
        content:'SÉLECTION OFFICIELLE'!important;
      }
      #characters .hc-person[data-id="ines"] .tag:after{display:none!important}
      #characters .hc-focus[data-hc-person="ines"] .hc-focus-portrait-final img,
      #characters .hc-focus-header-v2[data-id="ines"] .portrait img{
        width:100%!important;height:100%!important;
        object-fit:cover!important;
        object-position:50% 32%!important;
        transform:none!important;
        filter:none!important;
        mix-blend-mode:normal!important;
      }
    `;
    document.head.appendChild(s);
  }

  function mountCard(){
    const card=$('#characters .hc-person[data-id="ines"]');
    if(!card)return false;
    const fig=$('.fig',card);
    if(!fig)return false;
    let img=$('img.hc-ines-official-v7',fig);
    if(!img){
      fig.innerHTML='';
      img=document.createElement('img');
      img.className='hc-ines-official-v7';
      img.alt='Inès';
      fig.appendChild(img);
    }
    if(img.src!==FULL)img.src=FULL;
    card.dataset.hcOfficial='1';
    return true;
  }

  function mountFocus(){
    const card=$('#characters .hc-person.focused');
    const focus=$('#characters .hc-focus');
    if(!card||!focus||card.dataset.id!=='ines')return;
    focus.dataset.hcPerson='ines';

    const selectors=[
      '.hc-focus-portrait-final img',
      '.hc-focus-header-v2 .portrait img',
      '.portrait img'
    ];
    for(const sel of selectors){
      const img=$(sel,focus);
      if(img){img.src=PORTRAIT;img.alt='Portrait officiel d’Inès';}
    }

    const title=$('.hc-focus-title-final h3',focus)||$('h3',focus);
    if(title&&title.textContent.trim()!=='Inès')title.textContent='Inès';
    const vibe=$('.hc-focus-title-final .vibe',focus)||$('.vibe',focus);
    if(vibe)vibe.textContent='Solaire · couleur & mouvement';
  }

  function sync(){
    installCss();
    mountCard();
    mountFocus();
  }

  function boot(){
    sync();
    let n=0;
    const timer=setInterval(()=>{sync();if(++n>80)clearInterval(timer)},100);
    const root=$('#characters');
    if(root){
      new MutationObserver(()=>sync()).observe(root,{childList:true,subtree:true,attributes:true,attributeFilter:['class']});
    }
    document.addEventListener('click',e=>{
      if(e.target.closest?.('#characters .hc-person,#characters .hc-focus-nav,#characters [data-profile]')){
        setTimeout(sync,0);
        setTimeout(sync,80);
      }
    },true);
  }

  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});
  else boot();
})();